const state={zoom:1,x:0,y:0,query:'',source:'',status:'',filters:false,ap:null,mapHidden:false};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clock=us=>us?new Date(us/1000).toISOString().slice(11,23)+' UTC':'Not observed';
const seconds=us=>us==null?'Association not yet observed':(us/1e6).toFixed(3)+' s';
export const layoutManifest={layout_id:'airframe-illustrative-01',version:'1.0',origin:'illustrative',bounds:[0,0,1000,700],disclosure:'Illustrative layout · placements estimated',placements:[['AP-01',134,71],['AP-02',495,71],['AP-03',848,71],['AP-04',604,342],['AP-05',135,625],['AP-06',369,625],['AP-07',637,625],['AP-08',856,625]].map(([alias,x,y])=>({alias,x,y,origin:'illustrative'}))};
function geometry(){
 const racks=(x,y,n=5)=>Array.from({length:n},(_,i)=>`<g transform="translate(${x+i*34} ${y})"><rect class="equipment" width="23" height="87"/><path class="fine" d="M0 14h23M0 28h23M0 42h23M0 56h23M0 70h23M11.5 0v87"/>${[4,18,32,46,60,74].map(t=>`<rect class="secondary" x="3" y="${t}" width="6" height="8"/><rect class="secondary" x="14" y="${t}" width="6" height="8"/>`).join('')}</g>`).join('');
 const cells=Array.from({length:5},(_,i)=>`<g transform="translate(${133+i*103} 148)"><rect class="zone-fill" width="89" height="148"/><path class="secondary" d="M5 5h79v137H5zM0 111h89M13 0v-11h60v11"/><rect class="equipment" x="20" y="18" width="51" height="18"/><rect class="equipment" x="23" y="119" width="43" height="15"/><circle class="equipment" cx="43" cy="91" r="11"/><path stroke="#90a4ae" stroke-width="4" d="M43 91l-16-28 16-18 15 22"/><circle class="equipment" cx="27" cy="63" r="5"/><circle class="equipment" cx="43" cy="45" r="4"/><path class="secondary" d="M58 62l8 10-8 6M11 14v86M77 14v86"/><text class="small-label" x="10" y="109">CELL 0${i+1}</text></g>`).join('');
 return `<defs><pattern id="floorGrid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" fill="none" stroke="#334550" stroke-width=".35" opacity=".35"/></pattern><pattern id="attentionHatch" width="10" height="10" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><line x1="0" y1="0" x2="0" y2="10" stroke="#ffbe45" stroke-width="1" opacity=".2"/></pattern></defs><rect width="1000" height="700" fill="url(#floorGrid)"/><g class="floor-geometry"><path class="walls" d="M25 24H973V667H25zM30 29H968V662H30zM99 90H705V315H99zM104 95H700V310H104zM732 91H938V306H732zM737 96H933V301H737zM99 397H282V600H99zM104 402H277V595H104zM303 397H705V649H303zM308 402H700V644H308zM732 397H938V649H732zM737 402H933V644H737z"/><path class="aisle" d="M76 52v574M75 365H914M116 74H682M716 76v569M120 380H913M318 521H686M765 324v54M952 88v532"/><path class="secondary" d="M34 43h61v26H34zM34 92h30v90H34zM34 208h30v90H34zM34 404h30v98H34zM34 530h30v112H34zM144 34h283v20H144zM459 34h220v20H459zM744 34h158v20H744zM908 34h38v34H908z"/>${cells}<path class="equipment" d="M119 267H688V279H119z"/><path class="fine" d="M120 271H687M120 275H687"/><text class="label" x="136" y="124">Assembly</text><text class="small-label" x="568" y="124">PRODUCTION CELLS</text><text class="label" x="753" y="124">Test</text><g>${[0,1,2].map(i=>`<rect class="equipment" x="${757+i*55}" y="151" width="37" height="96"/><rect class="secondary" x="${763+i*55}" y="164" width="25" height="28"/><path class="fine" d="M${757+i*55} 210h37m-37 8h37m-37 8h37m-37 8h37"/>`).join('')}</g><rect class="equipment" x="761" y="266" width="134" height="16"/><path class="secondary" d="M118 319v31h132v-31M125 325h26v21h-26zM157 325h26v21h-26zM189 325h26v21h-26zM221 325h22v21h-22z"/><text class="label" x="329" y="438">Logistics</text><text class="small-label" x="582" y="438">STORAGE + STAGING</text>${racks(327,458,10)}${racks(327,559,10)}${racks(117,434,4)}<text class="small-label" x="122" y="574">MATERIAL PREP</text><text class="label" x="755" y="435">Loading</text>${[0,1,2].map(i=>`<g transform="translate(765 ${463+i*59})"><rect class="equipment" width="129" height="39"/><rect class="secondary" x="6" y="5" width="100" height="29"/><path class="secondary" d="M117 0v39M129 8h16v23h-16M40 0v39M74 0v39"/></g>`).join('')}<path class="secondary" d="M281 648v-31h-98v31M124 647v-30h32v30M725 317h211M725 386h211"/>${Array.from({length:18},(_,i)=>`<path class="secondary" d="M${35+i*54} 24v11M${35+i*54} 667v-11"/>`).join('')}${Array.from({length:11},(_,i)=>`<path class="secondary" d="M25 ${40+i*56}h10M973 ${40+i*56}h-10"/>`).join('')}</g>`;
}
export function renderFactory(container,ctx){
 let disposed=false,drag=null,rendered=false;
 const incidents=ctx.service.listInvestigations?ctx.service.listInvestigations(ctx.context):ctx.service.listIncidents(ctx.context);
 const sources=ctx.service.getSources?ctx.service.getSources(ctx.context):ctx.service.manifest.sources;
 const selected=incidents.find(i=>i.id===ctx.selectedIncidentId)||null;
 function filtered(){return incidents.filter(i=>(!state.query||`${i.id} ${i.client} ${i.ap}`.toLowerCase().includes(state.query.toLowerCase()))&&(!state.source||(i.evidence||[]).some(e=>e.source===state.source||e.source_id===state.source||e.sourceId===state.source))&&(!state.status||(state.status==='association_observed'?i.endUs!=null:i.endUs==null)));}
 const activeCount=()=>[state.query,state.source,state.status].filter(Boolean).length;
 const card=i=>`<button class="incident-card ${i.id===ctx.selectedIncidentId?'is-selected':''}" data-select="${esc(i.id)}" aria-pressed="${i.id===ctx.selectedIncidentId}"><span><span class="incident-id">${esc(i.id)}</span><span class="incident-dot"></span></span><span><strong>${esc(i.anchors?.deauth?.reasonCode===23?'Reported 802.1X failure':i.title||'Reported disconnect')}</strong><span class="client-label">Client ${esc(i.client)} · ${esc(i.ap)}</span><span class="card-detail">${i.durationUs==null?'Sequence in progress':seconds(i.durationUs)} <span aria-hidden="true">·</span> ${i.viewpoints||0} channel viewpoints</span></span><span class="chevron" aria-hidden="true">›</span></button>`;
 function selectedRegion(s,p){
  const x=Math.max(36,Math.min(690,p.x-165)),y=Math.max(36,Math.min(586,p.y-30)),cx=p.x>200?p.x-102:p.x+115,cy=p.y+13;
  return `<g class="illustrative-selected-context"><rect x="${x}" y="${y}" width="270" height="72" fill="#ffbe4510" stroke="#ffbe45" stroke-dasharray="5 4"/><rect x="${x}" y="${y}" width="270" height="72" fill="url(#attentionHatch)"/><rect x="${x+7}" y="${y+3}" width="247" height="18" rx="3" fill="#211c13"/><text x="${x+13}" y="${y+16}" fill="#ffbe45" font-size="10" font-family="sans-serif">Illustrative incident placement · ${esc(s.id)}</text><path d="M${cx} ${cy}L${p.x} ${p.y}" stroke="#8fcbff" stroke-dasharray="4 3"/><circle cx="${cx}" cy="${cy}" r="8" fill="#193243" stroke="#8fcbff" stroke-width="2"/><circle cx="${cx}" cy="${cy}" r="4" fill="#8fcbff"/><text x="${cx+14}" y="${cy+4}" fill="#8fcbff" font-size="11" font-family="monospace">${esc(s.client)}</text></g>`;
 }
 function map(){let s=selected&&filtered().some(i=>i.id===selected.id)?selected:null;let place=s&&layoutManifest.placements.find(p=>p.alias===s.ap);return `<svg class="floor-svg" viewBox="0 0 1000 700" aria-label="Illustrative factory layout with eight estimated access point contexts"><g data-floor-transform>${geometry()}${place?selectedRegion(s,place):''}${layoutManifest.placements.map(p=>`<g class="floor-marker ${p.alias===s?.ap?'selected':''}" role="button" tabindex="0" data-ap="${p.alias}" aria-label="${p.alias}, illustrative placement; show context" transform="translate(${p.x} ${p.y})"><rect x="-17" y="-20" width="82" height="42" fill="transparent"/><circle class="marker-disc" r="10"/><circle cx="0" cy="0" r="3" fill="${p.alias===s?.ap?'#ffbe45':'#a0b9ca'}"/><text x="17" y="4">${p.alias}</text></g>`).join('')}</g></svg>`;}
 function render(){if(disposed)return;if(rendered&&ctx.refresh){ctx.refresh();return;}rendered=true;let visible=filtered(),current=visible.find(i=>i.id===selected?.id);container.innerHTML=`<div class="factory-view"><div class="factory-grid"><section class="factory-map-section ${state.mapHidden?'map-hidden':''}" aria-label="Factory context"><div class="factory-heading"><div><h1>Factory overview</h1><p>Locate the next investigation</p></div><div class="factory-location"><strong>PRODUCTION FLOOR</strong>Architectural context · Level 01</div><button class="btn mobile-map-toggle" data-toggle-map>${state.mapHidden?'Show':'Hide'} map</button></div><div class="floor-panel"><div class="floor-viewport">${map()}<div class="floor-controls" aria-label="Map controls"><button data-zoom="in" aria-label="Zoom in">+</button><button data-zoom="out" aria-label="Zoom out">−</button><button data-zoom="reset" aria-label="Reset map view">⌖</button></div><div class="floor-legend"><span></span>LOGICAL AP CONTEXTS</div><div data-map-context></div></div><div class="floor-caption"><span>DRAG TO PAN · ${Math.round(state.zoom*100)}% VIEW</span><span title="Factory geometry and device positions are designed for context; packet evidence does not establish physical locations.">Illustrative layout · placements estimated</span></div></div></section><aside class="attention-rail" aria-label="Investigations"><div class="attention-heading"><div><h2>Needs attention</h2><p>${visible.length} curated investigation${visible.length===1?'':'s'}${activeCount()?' in this selection':''}</p></div><button class="icon-btn" data-filter-toggle aria-label="Filter investigations" aria-expanded="${state.filters}"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M3 4h18l-7 8v7l-4 2v-9z"/></svg>${activeCount()?`<span>${activeCount()}</span>`:''}</button></div>${state.filters?`<div class="filter-panel"><label>Find client, AP or investigation<input data-filter-query value="${esc(state.query)}" placeholder="e.g. C-004 or AP-04" type="search" aria-label="Find investigation"></label><div class="filter-row"><label>Source<select data-filter-source><option value="">All sources</option>${sources.map(s=>`<option ${s.id===state.source?'selected':''}>${esc(s.id)}</option>`).join('')}</select></label><label>Observed state<select data-filter-status><option value="">All states</option><option value="association_observed" ${state.status==='association_observed'?'selected':''}>Association observed</option><option value="pending" ${state.status==='pending'?'selected':''}>In progress</option></select></label></div><button class="filter-clear" data-filter-clear>Clear all filters</button></div>`:''}<div class="incident-list">${visible.length?visible.map(card).join(''):`<div class="empty-state"><h3>No investigations ${ctx.context?.mode==='capture_replay'?'observed at this replay time':'in this selection'}</h3><p>${activeCount()?'Try clearing your filters.':'The illustrative layout remains available for context.'}</p></div>`}</div><div class="selected-summary">${current?`<div class="summary-eyebrow"><span>Selected investigation</span><span class="mono">${esc(current.id)}</span></div><h3>${esc(current.anchors?.deauth?.reasonCode===23?'Reported 802.1X failure':current.title||'Reported disconnect')}</h3><dl class="summary-grid"><dt>Client</dt><dd class="mono">${esc(current.client)}</dd><dt>AP context</dt><dd class="mono">${esc(current.ap)}</dd><dt>Recorded interval</dt><dd class="mono">${seconds(current.durationUs)}</dd><dt>Channel viewpoints</dt><dd>${current.viewpoints||0} capture sources</dd><dt>First observed</dt><dd class="mono">${clock(current.openUs)}</dd><dt>Association response</dt><dd class="mono">${clock(current.endUs)}</dd><dt>Evidence</dt><dd>Partial</dd></dl><div class="cause-callout"><span class="cause-icon" aria-hidden="true">!</span><div><strong>Cause unresolved</strong><p>Association is not service recovery. Investigate authentication and session control; physical timing is unvalidated.</p></div></div><button class="btn btn-amber summary-open" data-open="${esc(current.id)}">Open investigation <span aria-hidden="true">→</span></button>`:`<div class="empty-state">${selected?'The selected investigation is outside these filters.':'Select an investigation to inspect its evidence.'}</div>`}</div></aside></div><footer class="source-strip"><div class="source-title"><strong>${sources.length} capture files loaded</strong><span>Recorded channel viewpoints</span></div><div class="source-items">${sources.map(s=>`<div class="source-item" title="${esc(s.id)} · ${Number(s.recordCount||0).toLocaleString()} captured records · sensor health unknown"><span class="source-file" aria-hidden="true"></span><div>${esc(s.id)}<small>CH ${esc(s.channel)}</small></div></div>`).join('')}</div><div class="source-trust">ⓘ &nbsp; Cross-source clock alignment unverified<span>Sensor health unavailable · recorded captures</span></div></footer></div>`;bind();transform();showMapContext();}
 function transform(){const el=container.querySelector('[data-floor-transform]');if(el)el.setAttribute('transform',`translate(${500+state.x} ${350+state.y}) scale(${state.zoom}) translate(-500 -350)`);const caption=container.querySelector('.floor-caption span');if(caption)caption.textContent=`DRAG TO PAN · ${Math.round(state.zoom*100)}% VIEW`;}
 function showMapContext(){const host=container.querySelector('[data-map-context]');if(!host)return;host.innerHTML=state.ap?`<div class="map-context"><div class="map-context-header"><strong class="mono">${esc(state.ap)}</strong><button data-close-context aria-label="Close AP context">×</button></div><p>Logical BSSID context · illustrative placement</p>${incidents.filter(i=>i.ap===state.ap).map(i=>`<button class="btn" data-open="${esc(i.id)}">${esc(i.id)} · ${esc(i.client)} <span>→</span></button>`).join('')||'<p>No matching investigation in the available selection. This does not establish network health.</p>'}</div>`:'';host.querySelector('[data-close-context]')?.addEventListener('click',()=>{state.ap=null;showMapContext();});host.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>ctx.onOpen(b.dataset.open));}
 function bind(){container.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>ctx.onSelect(b.dataset.select));container.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>ctx.onOpen(b.dataset.open));container.querySelector('[data-filter-toggle]').onclick=()=>{state.filters=!state.filters;render();container.querySelector(state.filters?'[data-filter-query]':'[data-filter-toggle]')?.focus();};container.querySelector('[data-filter-query]')?.addEventListener('input',e=>{const pos=e.target.selectionStart;state.query=e.target.value;render();const input=container.querySelector('[data-filter-query]');input.focus();input.setSelectionRange(pos,pos);});container.querySelector('[data-filter-source]')?.addEventListener('change',e=>{state.source=e.target.value;render();container.querySelector('[data-filter-source]').focus();});container.querySelector('[data-filter-status]')?.addEventListener('change',e=>{state.status=e.target.value;render();container.querySelector('[data-filter-status]').focus();});container.querySelector('[data-filter-clear]')?.addEventListener('click',()=>{state.query='';state.source='';state.status='';render();container.querySelector('[data-filter-query]')?.focus();});container.querySelector('[data-toggle-map]').onclick=()=>{state.mapHidden=!state.mapHidden;render();};container.querySelectorAll('[data-ap]').forEach(m=>{m.onclick=()=>{state.ap=m.dataset.ap;showMapContext();};m.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();m.click();}};});container.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{if(b.dataset.zoom==='reset'){state.zoom=1;state.x=state.y=0;}else state.zoom=Math.max(1,Math.min(2.6,state.zoom+(b.dataset.zoom==='in'?.25:-.25)));transform();});const viewport=container.querySelector('.floor-viewport');viewport.onpointerdown=e=>{if(e.target.closest('button,[role=button],.map-context'))return;drag={x:e.clientX,y:e.clientY,px:state.x,py:state.y};viewport.setPointerCapture(e.pointerId);};viewport.onpointermove=e=>{if(!drag)return;const scale=1000/viewport.clientWidth;state.x=Math.max(-300,Math.min(300,drag.px+(e.clientX-drag.x)*scale));state.y=Math.max(-220,Math.min(220,drag.py+(e.clientY-drag.y)*scale));transform();};viewport.onpointerup=viewport.onpointercancel=()=>drag=null;}
 function bindMarkerKeyboard(){container.querySelectorAll('[data-ap]').forEach(marker=>{marker.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();state.ap=marker.dataset.ap;showMapContext();}else if(e.key==='Escape'){state.ap=null;showMapContext();}};});}
 const initialBind=()=>{bindOriginal();bindMarkerKeyboard();};
 const bindOriginal=bind;
 bind=function(){initialBind();container.querySelectorAll('button,input,select,[data-ap]').forEach((el,n)=>{el.id='factory-'+(el.dataset.select||el.dataset.ap||(el.dataset.open?'open-'+el.dataset.open:el.dataset.zoom?'zoom-'+el.dataset.zoom:el.hasAttribute('data-filter-query')?'filter-query':el.hasAttribute('data-filter-source')?'filter-source':el.hasAttribute('data-filter-status')?'filter-status':el.hasAttribute('data-filter-toggle')?'filter-toggle':el.hasAttribute('data-filter-clear')?'filter-clear':el.hasAttribute('data-toggle-map')?'toggle-map':'control-'+n));});const viewport=container.querySelector('.floor-viewport');viewport.id='factory-map-viewport';viewport.tabIndex=0;viewport.setAttribute('aria-label','Illustrative floor map. Use arrow keys to pan; Home resets the view.');viewport.onkeydown=e=>{if(e.target!==viewport)return;const delta={ArrowLeft:[25,0],ArrowRight:[-25,0],ArrowUp:[0,25],ArrowDown:[0,-25]}[e.key];if(delta){e.preventDefault();state.x=Math.max(-300,Math.min(300,state.x+delta[0]));state.y=Math.max(-220,Math.min(220,state.y+delta[1]));transform();}else if(e.key==='Home'){e.preventDefault();state.zoom=1;state.x=state.y=0;transform();}};};
 try{render();}catch(error){container.innerHTML='<div class="factory-error"><h2>Investigation view unavailable</h2><p>Capture evidence could not be displayed. Return to Factory to retry.</p></div>';ctx.notify?.(error.message);}
 return()=>{disposed=true;drag=null;};
}
